(function (racine) {
  racine.MMA_ECRAN = {
    gabarit: "<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Fight Night</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Anton&family=Barlow+Semi+Condensed:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{--nuit:#12161e;--nuit-2:#1a2029;--tungstene:#f2b25a;--craie:#e9e5da;\n        --craie-2:#9aa0a8;--cuir:#b6412f;--trait:#2a323d;--bleu:#5f8fc4}\n  *{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}\n  html,body{height:100%}\n  body{background:var(--nuit);color:var(--craie);font-family:\"Barlow Semi Condensed\",system-ui,sans-serif;overflow:hidden;user-select:none}\n  .app{max-width:430px;margin:0 auto;height:100dvh;display:flex;flex-direction:column;position:relative}\n\n  .entete{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:12px 14px 6px;gap:8px}\n  .coin{min-width:0;cursor:pointer}\n  .coin b{font-family:Anton;font-weight:400;letter-spacing:.04em;font-size:.95rem;text-transform:uppercase;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .coin span{font-size:.66rem;color:var(--craie-2)}\n  .coin.d{text-align:right}\n  .coin i{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:6px;vertical-align:1px}\n  .coin.d i{margin:0 0 0 6px}\n  .horloge{text-align:center}\n  .horloge b{font-variant-numeric:tabular-nums;font-size:1.25rem;font-weight:700;letter-spacing:.04em}\n  .horloge span{display:block;font-size:.6rem;letter-spacing:.18em;color:var(--craie-2);font-weight:600}\n\n  .momentum{height:5px;margin:4px 14px 0;border-radius:3px;background:#242b35;overflow:hidden;display:flex}\n  .momentum .a{background:var(--tungstene);transition:width 1s}\n  .momentum .b{background:var(--bleu);flex:1}\n\n  .cartes{display:flex;gap:5px;justify-content:center;padding:6px 12px 0;min-height:0}\n  .cartes .c{font-size:.6rem;font-weight:700;letter-spacing:.04em;\n    background:var(--nuit-2);border:1px solid var(--trait);border-radius:6px;\n    padding:2px 7px;font-variant-numeric:tabular-nums}\n  .cartes .c small{color:var(--craie-2);font-weight:600;margin-right:4px}\n  .cartes .c .g{color:var(--tungstene)} .cartes .c .d{color:var(--bleu)}\n  .cartes .tot{border-color:var(--tungstene)}\n\n  .direct{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;padding:8px 12px 2px}\n  .cel{background:var(--nuit-2);border:1px solid var(--trait);border-radius:8px;padding:4px 0;text-align:center}\n  .cel small{display:block;font-size:.5rem;letter-spacing:.14em;color:var(--craie-2);font-weight:700}\n  .cel b{font-variant-numeric:tabular-nums;font-size:.76rem;font-weight:700}\n  .cel b .g{color:var(--tungstene)} .cel b .d{color:var(--bleu)}\n  .cel b .sep{color:#4a5361;font-weight:400;padding:0 3px}\n\n  .scene{flex:1;position:relative;min-height:0;display:flex;align-items:center;justify-content:center}\n  .scene svg{width:min(100%,430px);height:100%;display:block}\n  .phase{position:absolute;top:8px;left:50%;transform:translateX(-50%);\n    font-size:.66rem;font-weight:700;letter-spacing:.2em;color:var(--craie-2);\n    background:rgba(18,22,30,.7);padding:3px 12px;border-radius:10px}\n  .phase.chaud{color:var(--tungstene)}\n  #criEcho{position:absolute;left:50%;top:34%;transform:translate(-50%,-50%) scale(.8);\n    font-size:21px;font-weight:800;text-align:center;padding:10px 18px;border-radius:14px;\n    background:rgba(10,12,16,.88);border:1.5px solid var(--or);color:var(--or);\n    opacity:0;pointer-events:none;z-index:40;transition:opacity .25s,transform .25s;\n    max-width:82%}\n  #criEcho.perdu{border-color:var(--doux);color:var(--doux)}\n  #criEcho.on{opacity:1;transform:translate(-50%,-50%) scale(1)}\n  .flash{position:absolute;inset:0;background:var(--cuir);opacity:0;pointer-events:none}\n  .flash.on{animation:fl .5s}\n  @keyframes fl{20%{opacity:.28}100%{opacity:0}}\n  .pt{cursor:pointer}\n\n  /* entre-rounds : le tapis respire, on comprend sans lire */\n  .gong{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);\n    font-family:Anton;font-size:1.6rem;letter-spacing:.12em;color:var(--tungstene);\n    opacity:0;pointer-events:none}\n  .gong.on{animation:go 1.6s}\n  @keyframes go{0%{opacity:0;transform:translate(-50%,-50%) scale(.9)}\n                25%{opacity:1}75%{opacity:1}100%{opacity:0}}\n\n  .corps{position:absolute;bottom:8px;width:48px}\n  .corps.g{left:10px}.corps.d{right:10px}\n  .corps svg{width:100%}\n  .corps .z{fill:#232b36;transition:fill .8s}\n\n  .commentaire{min-height:48px;display:flex;align-items:center;justify-content:center;\n    padding:4px 22px;text-align:center;font-size:.9rem;line-height:1.3;color:#d8d3c6}\n  .commentaire.pop{animation:pop .35s}\n  @keyframes pop{0%{opacity:0;transform:translateY(6px)}100%{opacity:1}}\n\n  .essences{display:flex;gap:10px;padding:0 14px 8px}\n  .ess{flex:1;height:4px;border-radius:2px;background:#242b35;overflow:hidden}\n  .ess i{display:block;height:100%;border-radius:2px;transition:width 1.2s}\n  .ess.g i{background:var(--tungstene)}.ess.d i{background:var(--bleu);margin-left:auto}\n\n  .ctl{display:flex;gap:8px;padding:0 14px calc(14px + env(safe-area-inset-bottom))}\n  .ctl button{flex:1;padding:12px 4px;border-radius:12px;border:1px solid var(--trait);\n    background:var(--nuit-2);color:var(--craie);font-family:inherit;font-weight:700;font-size:.78rem;\n    letter-spacing:.05em;cursor:pointer}\n  .ctl button.plein{background:var(--tungstene);border-color:var(--tungstene);color:#1a1206}\n  .ctl button:focus-visible{outline:2px solid var(--tungstene);outline-offset:2px}\n\n  /* /!\\ LA CARTE DE FIN PREND TOUT L'ECRAN (Mael, teste sur telephone :\n     \"fin de combat illisible\"). Elle etait posee DANS la scene, en semi\n     transparent : le compteur de stats, le commentaire et les boutons de\n     lecture restaient visibles PAR-DESSOUS et les textes se croisaient.\n     Fond opaque, position fixe, au-dessus de tout. */\n  .fin{position:fixed;inset:0;background:var(--nuit);display:none;\n    align-items:center;justify-content:center;flex-direction:column;gap:8px;z-index:50;text-align:center;padding:24px}\n  .fin.la{display:flex}\n  .fin small{letter-spacing:.24em;color:var(--craie-2);font-weight:600;font-size:.7rem}\n  .fin h1{font-family:Anton;font-weight:400;font-size:2rem;letter-spacing:.05em;text-transform:uppercase}\n  .fin p{color:var(--tungstene);font-weight:700;letter-spacing:.08em}\n  .fin button{padding:12px 22px;border-radius:12px;border:0;background:var(--tungstene);\n    color:#1a1206;font-family:inherit;font-weight:700;font-size:.83rem;cursor:pointer}\n\n  /* /!\\ AU-DESSUS DE LA CARTE DE FIN (Mael, en jouant : \"les boutons\n     n'etaient pas cliquables\"). En passant .fin a z-index 50 pour la\n     rendre lisible, j'avais fait passer la feuille de stats DERRIERE\n     elle : elle s'ouvrait, invisible, et le bouton semblait mort. */\n  .stats{position:fixed;inset:0;background:var(--nuit);display:none;\n    flex-direction:column;z-index:60;padding:18px 16px calc(16px + env(safe-area-inset-bottom));overflow:auto}\n  .stats.la{display:flex}\n  .stats .tete{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;margin-bottom:4px}\n  .stats .tete b{font-family:Anton;font-weight:400;font-size:1rem;letter-spacing:.04em;text-transform:uppercase}\n  .stats .tete .vs{font-size:.6rem;letter-spacing:.22em;color:var(--craie-2);font-weight:700}\n  .stats .tete .d{text-align:right}\n  .stats .verdict{text-align:center;font-size:.72rem;color:var(--tungstene);font-weight:700;letter-spacing:.1em;margin-bottom:12px}\n  .stats h3{font-size:.62rem;letter-spacing:.22em;color:var(--craie-2);font-weight:700;text-align:center;margin:14px 0 8px}\n  .ligne{display:grid;grid-template-columns:46px 1fr 92px 1fr 46px;align-items:center;gap:8px;font-size:.78rem;margin-bottom:7px}\n  .ligne b{font-variant-numeric:tabular-nums;font-weight:700}\n  .ligne b:last-child{text-align:right}\n  .ligne .lib{text-align:center;font-size:.66rem;color:var(--craie-2);font-weight:600}\n  .demi{height:6px;border-radius:3px;background:#242b35;overflow:hidden;display:flex}\n  .demi.g{justify-content:flex-end}\n  .demi i{display:block;height:100%}\n  .demi.g i{background:var(--tungstene);border-radius:3px 0 0 3px}\n  .demi.d i{background:var(--bleu);border-radius:0 3px 3px 0}\n  .ligne .gagne{color:var(--tungstene)}\n  .stats .fermer{margin-top:14px;padding:12px;border-radius:12px;border:1px solid var(--trait);\n    background:var(--nuit-2);color:var(--craie);font-family:inherit;font-weight:700;font-size:.82rem;cursor:pointer}\n\n  @media (prefers-reduced-motion:reduce){*{animation:none !important;transition:none !important}}\n/* ---- LE COIN DU COACH ----\n   /!\\ PAS .coin : cette classe designe deja les coins rouge/bleu des\n   combattants en tete d'ecran. Collision evitee de justesse. */\n#coach{position:fixed;inset:0;z-index:60;background:rgba(6,9,14,.88);\n  display:none;align-items:center;justify-content:center;padding:18px;\n  backdrop-filter:blur(3px)}\n#coach.la{display:flex}\n#coach .c-boite{width:100%;max-width:380px;background:var(--nuit-2);\n  border:1px solid var(--trait);border-radius:12px;padding:16px 15px 15px}\n#coach .c-tete{font-family:Anton,sans-serif;font-size:1.15rem;letter-spacing:.03em;\n  color:var(--tungstene)}\n#coach .c-sous{font-size:.72rem;color:var(--craie-2);margin:2px 0 12px}\n#coach .c-lib{font-size:.62rem;letter-spacing:.1em;text-transform:uppercase;\n  color:var(--craie-2);margin:11px 0 5px}\n#coach .c-rang{display:flex;gap:6px}\n.cbtn{flex:1;padding:9px 4px;border-radius:7px;cursor:pointer;\n  background:var(--nuit);border:1px solid var(--trait);color:var(--craie);\n  font-family:inherit;font-size:.78rem}\n.cbtn.actif{background:var(--tungstene);border-color:var(--tungstene);\n  color:#12161e;font-weight:700}\n/* LE RESSENTI (chantier grave au cas 104) : il parle AVANT les consignes.\n   Deux voix qui peuvent se contredire — ce qu'il DIT, et ce que tu VOIS. */\n#coach .c-dit{background:var(--nuit);border:1px solid var(--trait);border-left:3px solid var(--tungstene);\n  border-radius:9px;padding:10px 11px;margin:2px 0 4px}\n#coach .c-dit p{font-size:.86rem;line-height:1.42;font-style:italic;margin:0}\n#coach .c-etat{font-size:.6rem;letter-spacing:.1em;text-transform:uppercase;\n  color:var(--craie-2);margin-bottom:4px}\n#coach .c-etat b{font-style:normal;letter-spacing:.06em}\n#coach .c-etat b.dur{color:var(--cuir)}\n#coach .c-signes{font-size:.7rem;color:var(--craie-2);line-height:1.4;margin:6px 0 2px}\n#coach .c-signes span{display:block}\n#coach .c-signes span:before{content:\"— \"}\n#coach .c-demande{width:100%;margin-top:8px;padding:9px;border-radius:8px;cursor:pointer;\n  background:var(--nuit-2);border:1px dashed var(--tungstene);color:var(--tungstene);\n  font-family:inherit;font-size:.75rem}\n#coach .c-demande.pris{border-style:solid;background:var(--tungstene);color:#12161e;font-weight:700}\n#coach .c-note{font-size:.66rem;color:var(--craie-2);margin:12px 0 10px;text-align:center}\n#coach .c-go{width:100%;padding:12px;border-radius:8px;cursor:pointer;\n  background:var(--cuir);border:1px solid var(--cuir);color:#fff;\n  font-family:Anton,sans-serif;font-size:.95rem;letter-spacing:.05em}\n/* ---- LES CRIS DU CHANTIER G ----\n   Le panneau se superpose SANS mettre le combat en pause : un vrai coin\n   crie pendant l'action. Le cri part a la prochaine tranche de 30 s. */\n#crier{position:fixed;left:0;right:0;bottom:0;z-index:55;\n  background:rgba(12,16,24,.96);border-top:1px solid var(--trait);\n  padding:10px 14px calc(12px + env(safe-area-inset-bottom));display:none}\n#crier.la{display:block}\n#crier .cr-tete{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px}\n#crier .cr-tete b{font-family:Anton;font-weight:400;font-size:.9rem;letter-spacing:.06em;color:var(--tungstene)}\n#crier .cr-tete span{font-size:.66rem;color:var(--craie-2);font-weight:600}\n#crier .cr-liste{display:flex;flex-wrap:wrap;gap:7px}\n.cri-b{padding:9px 12px;border-radius:9px;cursor:pointer;\n  background:var(--nuit-2);border:1px solid var(--trait);color:var(--craie);\n  font-family:inherit;font-size:.8rem;font-weight:600}\n.cri-b.choisi{background:var(--cuir);border-color:var(--cuir);color:#fff}\n#btnCrier.arme{background:var(--cuir);border-color:var(--cuir);color:#fff}\n</style>\n</head>\n<body>\n<div class=\"app\">\n\n  <div class=\"entete\">\n    <div class=\"coin\" onclick=\"voirStats()\"><b><i style=\"background:var(--tungstene)\"></i><span id=\"nomA\">—</span></b><span id=\"ficheA\"></span></div>\n    <div class=\"horloge\"><b id=\"clk\">5:00</b><span id=\"rnd\">ROUND 1</span></div>\n    <div class=\"coin d\" onclick=\"voirStats()\"><b><span id=\"nomB\">—</span><i style=\"background:var(--bleu)\"></i></b><span id=\"ficheB\"></span></div>\n  </div>\n\n  <div class=\"momentum\"><div class=\"a\" id=\"mom\" style=\"width:50%\"></div><div class=\"b\"></div></div>\n\n  <!-- LES CARTES DES JUGES, round par round. /!\\ Elles viennent du LOG :\n       c'est le moteur qui a juge, l'ecran ne rejuge rien. -->\n  <div class=\"cartes\" id=\"cartes\"></div>\n\n  <div class=\"direct\">\n    <div class=\"cel\"><small>SIG.</small><b id=\"dSig\"></b></div>\n    <div class=\"cel\"><small>FRAPPES</small><b id=\"dFr\"></b></div>\n    <div class=\"cel\"><small>TAKEDOWNS</small><b id=\"dTd\"></b></div>\n    <div class=\"cel\"><small>CONTRÔLE</small><b id=\"dCt\"></b></div>\n    <div class=\"cel\"><small>SOUM.</small><b id=\"dSub\"></b></div>\n  </div>\n\n  <div class=\"scene\" id=\"scene\">\n    <svg viewBox=\"0 0 360 360\">\n      <defs><radialGradient id=\"tapis\" cx=\"50%\" cy=\"50%\" r=\"60%\">\n        <stop offset=\"0%\" stop-color=\"#1d2530\"/><stop offset=\"100%\" stop-color=\"#141a24\"/>\n      </radialGradient></defs>\n      <polygon id=\"oct\" class=\"oct\" points=\"\" fill=\"url(#tapis)\" stroke=\"#3a4452\" stroke-width=\"5\"/>\n      <polygon id=\"oct2\" points=\"\" fill=\"none\" stroke=\"#243040\" stroke-width=\"1.5\"/>\n      <circle cx=\"180\" cy=\"180\" r=\"34\" fill=\"none\" stroke=\"#243040\" stroke-width=\"1.5\"/>\n      <text id=\"posSol\" x=\"180\" y=\"150\" text-anchor=\"middle\" fill=\"#f2b25a\" font-size=\"11\" font-weight=\"700\" letter-spacing=\"2\" opacity=\"0\"></text>\n      <g id=\"pA\" class=\"pt\" onclick=\"voirStats()\"><circle r=\"12\" fill=\"#f2b25a\" opacity=\".2\"/><circle r=\"7\" fill=\"#f2b25a\" stroke=\"#12161e\" stroke-width=\"2\"/></g>\n      <g id=\"pB\" class=\"pt\" onclick=\"voirStats()\"><circle r=\"12\" fill=\"#5f8fc4\" opacity=\".2\"/><circle r=\"7\" fill=\"#5f8fc4\" stroke=\"#12161e\" stroke-width=\"2\"/></g>\n    </svg>\n    <div class=\"phase\" id=\"phase\">DISTANCE</div>\n    <div class=\"flash\" id=\"flash\"></div>\n    <div id=\"criEcho\"></div>\n    <div class=\"gong\" id=\"gong\"></div>\n\n    <div class=\"corps g\"><svg viewBox=\"0 0 40 90\">\n      <circle class=\"z\" id=\"At\" cx=\"20\" cy=\"12\" r=\"9\"/><rect class=\"z\" id=\"Ac\" x=\"10\" y=\"24\" width=\"20\" height=\"30\" rx=\"6\"/>\n      <rect class=\"z\" id=\"Aj\" x=\"12\" y=\"57\" width=\"7\" height=\"30\" rx=\"3\"/><rect class=\"z\" id=\"Aj2\" x=\"21\" y=\"57\" width=\"7\" height=\"30\" rx=\"3\"/>\n    </svg></div>\n    <div class=\"corps d\"><svg viewBox=\"0 0 40 90\">\n      <circle class=\"z\" id=\"Bt\" cx=\"20\" cy=\"12\" r=\"9\"/><rect class=\"z\" id=\"Bc\" x=\"10\" y=\"24\" width=\"20\" height=\"30\" rx=\"6\"/>\n      <rect class=\"z\" id=\"Bj\" x=\"12\" y=\"57\" width=\"7\" height=\"30\" rx=\"3\"/><rect class=\"z\" id=\"Bj2\" x=\"21\" y=\"57\" width=\"7\" height=\"30\" rx=\"3\"/>\n    </svg></div>\n\n    <div class=\"fin\" id=\"fin\">\n      <small id=\"finTitre\">VICTOIRE</small>\n      <h1 id=\"finNom\"></h1>\n      <p id=\"finMethode\"></p>\n      <span style=\"font-size:.78rem;color:var(--craie-2)\" id=\"finBourse\"></span>\n      <div style=\"display:flex;gap:10px;margin-top:14px\">\n        <button style=\"background:none;border:1px solid var(--trait);color:var(--craie)\" onclick=\"voirStats()\">Feuille de stats</button>\n        <button onclick=\"rejouer()\">Revoir le combat</button>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"commentaire\" id=\"com\">Les deux hommes touchent les gants. C'est parti.</div>\n\n  <div class=\"essences\">\n    <div class=\"ess g\"><i id=\"essA\" style=\"width:100%\"></i></div>\n    <div class=\"ess d\"><i id=\"essB\" style=\"width:100%\"></i></div>\n  </div>\n\n  <div class=\"ctl\">\n    <button id=\"btnPause\" onclick=\"pause()\">⏸ PAUSE</button>\n    <button onclick=\"voirStats()\">STATS</button>\n    <button class=\"plein\" id=\"btnVit\" onclick=\"vitesse()\">×1</button>\n    <button id=\"btnCrier\" onclick=\"ouvrirCris()\">📣 CRIER</button>\n    <button id=\"btnSim\" onclick=\"simulerRound()\">⏭ SIMULER</button>\n  </div>\n\n  <!-- LE COIN : s'ouvre a chaque cloche en mode direct. Le combat ATTEND. -->\n  <div id=\"coach\">\n    <div class=\"c-boite\">\n      <div class=\"c-tete\" id=\"coinRound\">FIN DU ROUND 1</div>\n      <div class=\"c-sous\">Une minute avec ton combattant.</div>\n\n      <!-- IL PARLE D'ABORD. Le ressenti vient du moteur (js/ressenti.js) :\n           ce qu'il dit est SON avis, les signes sont ce que tu vois. -->\n      <div id=\"coinDit\"></div>\n\n      <div class=\"c-lib\">Plan de jeu</div>\n      <div class=\"c-rang\">\n        <button class=\"cbtn\" data-cle=\"plan\" data-val=\"frappe\" onclick=\"choisir('plan','frappe')\">Boxer</button>\n        <button class=\"cbtn\" data-cle=\"plan\" data-val=\"lutte\"  onclick=\"choisir('plan','lutte')\">Lutter</button>\n        <button class=\"cbtn\" data-cle=\"plan\" data-val=\"clinch\" onclick=\"choisir('plan','clinch')\">Clinch</button>\n      </div>\n\n      <div class=\"c-lib\">Allure</div>\n      <div class=\"c-rang\">\n        <button class=\"cbtn\" data-cle=\"allure\" data-val=\"eco\"  onclick=\"choisir('allure','eco')\">Économiser</button>\n        <button class=\"cbtn\" data-cle=\"allure\" data-val=\"fort\" onclick=\"choisir('allure','fort')\">Tout donner</button>\n      </div>\n\n      <div class=\"c-lib\">Au sol</div>\n      <div class=\"c-rang\">\n        <button class=\"cbtn\" data-cle=\"sol\" data-val=\"soumission\" onclick=\"choisir('sol','soumission')\">Chercher la soumission</button>\n      </div>\n\n      <div class=\"c-lib\">Cible</div>\n      <div class=\"c-rang\">\n        <button class=\"cbtn\" data-cle=\"cible\" data-val=\"tete\"   onclick=\"choisir('cible','tete')\">Tête</button>\n        <button class=\"cbtn\" data-cle=\"cible\" data-val=\"corps\"  onclick=\"choisir('cible','corps')\">Corps</button>\n        <button class=\"cbtn\" data-cle=\"cible\" data-val=\"jambes\" onclick=\"choisir('cible','jambes')\">Jambes</button>\n      </div>\n\n      <div class=\"c-note\">Rien de sélectionné = on ne change rien.</div>\n      <button class=\"c-go\" onclick=\"reprendre()\">▶ REPRENDRE LE COMBAT</button>\n    </div>\n  </div>\n\n  <!-- CHANTIER G : le coin crie pendant le round. Trois cris par round,\n       ceux de la phase reelle du moteur. Le cri s'applique a la tranche\n       de 30 s SUIVANTE — jamais a ce qui est deja calcule. -->\n  <div id=\"crier\">\n    <div class=\"cr-tete\"><b>CRIER DEPUIS LE COIN</b>\n      <span id=\"crReste\">3 cris restants</span></div>\n    <div class=\"cr-liste\" id=\"crListe\"></div>\n  </div>\n\n  <div class=\"stats\" id=\"stats\">\n    <div class=\"tete\"><b id=\"sNomA\"></b><span class=\"vs\">VS</span><b class=\"d\" id=\"sNomB\"></b></div>\n    <div class=\"verdict\" id=\"verdict\">ROUND 1 · EN COURS</div>\n    <h3>LE COMBAT</h3>\n    <div id=\"lignes-combat\"></div>\n    <h3 id=\"tete-frappes\">FRAPPES SIGNIFICATIVES</h3>\n    <div id=\"lignes-frappes\"></div>\n    <h3>SUR LE PAPIER</h3>\n    <div id=\"lignes-profil\"></div>\n    <button class=\"fermer\" onclick=\"fermerStats()\">Retour au combat</button>\n  </div>\n</div>\n\n<script>\n/* =====================================================================\n   BLOC DE DONNEES — sortie de traducteur.py, rien d'autre.\n   Pour rejouer un autre combat : remplacer ce bloc, ne rien toucher\n   en dessous.\n   ===================================================================== */\nconst DATA = /*__DATA__*/;\n\nlet   S      = DATA.S;\n/* Rejouer : en page autonome, un simple rechargement. En surcouche (iframe\n   srcdoc), location.reload() ne rejoue pas fiablement le document injecte :\n   on demande au parent de reconstruire l'ecran, avec la MEME graine donc le\n   MEME combat. */\n/* ============ LA CLOCHE ET LE COIN ============ */\n/* CE QU'IL DIT ENTRE LES ROUNDS. Envoye par le jeu, jamais calcule ici. */\nlet RESSENTI = DATA.ressenti || null;\nconst MOT_ETAT={frais:\"frais\",entamé:\"entamé\",touché:\"touché\",\"cassé\":\"cassé\"};\nfunction rendreRessenti(){\n  const z=$('coinDit'); if(!z)return;\n  if(!RESSENTI){z.innerHTML='';return;}\n  const R=RESSENTI, dur=(R.etat===\"touché\"||R.etat===\"cassé\");\n  /* /!\\ LES DEUX VOIX NE SE FONDENT PAS. Ce qu'il DIT est en italique,\n     a la premiere personne. Ce que tu VOIS est en dessous, sec. Quand\n     elles se contredisent, c'est au coach de trancher — c'est le sel du\n     coin, on ne le resout pas a sa place. */\n  z.innerHTML='<div class=\"c-dit\">'\n    +'<div class=\"c-etat\">Il est <b class=\"'+(dur?'dur':'')+'\">'+(MOT_ETAT[R.etat]||R.etat)+'</b></div>'\n    +'<p>« '+R.dit+' »</p>'\n    +(R.signes&&R.signes.length\n      ?'<div class=\"c-signes\">'+R.signes.map(x=>'<span>'+x+'</span>').join('')+'</div>':'')\n    +'</div>'\n    +(R.demande\n      ?'<button class=\"c-demande'+(demandePrise()?' pris':'')+'\" onclick=\"suivreSaDemande()\">'\n        +(demandePrise()?'✓ tu l\\'écoutes':'Faire ce qu\\'il demande')+'</button>'\n      :'');\n}\n/* Sa demande n'est pas un nouveau levier : c'est UN des boutons deja la,\n   pre-coche. Le ressenti mene aux consignes, il n'en invente pas. */\nfunction demandePrise(){\n  const d=RESSENTI&&RESSENTI.demande; if(!d)return false;\n  return Object.keys(d).filter(k=>k!==\"mot\").every(k=>ordre[k]===d[k]);\n}\nfunction suivreSaDemande(){\n  const d=RESSENTI&&RESSENTI.demande; if(!d)return;\n  const pris=demandePrise();\n  for(const k of Object.keys(d)){ if(k===\"mot\")continue;\n    if(pris)delete ordre[k]; else ordre[k]=d[k]; }\n  majBoutonsCoin(); rendreRessenti();\n}\nfunction cloche(){\n  if(FIN||fini)return;                 /* pas de coin apres la fin (15/08) */\n  attenteCoin=true; enPause=true;\n  crisRestants=3; criEnAttente=null;           /* la voix revient entre les rounds */\n  $('btnCrier').classList.remove('arme'); $('crier').classList.remove('la');\n  $('btnPause').textContent='▶ REPRENDRE';\n  ordre={};\n  $('coinRound').textContent=`FIN DU ROUND ${RD}`;\n  majBoutonsCoin();\n  rendreRessenti();\n  $('coach').classList.add('la');\n}\nfunction choisir(cle,valeur){\n  ordre[cle]=(ordre[cle]===valeur)?undefined:valeur;\n  if(ordre[cle]===undefined)delete ordre[cle];\n  majBoutonsCoin(); rendreRessenti();\n}\nfunction majBoutonsCoin(){\n  document.querySelectorAll('#coach [data-cle]').forEach(b=>{\n    const on = ordre[b.dataset.cle]===b.dataset.val\n      || (b.dataset.val==='' && ordre[b.dataset.cle]===undefined && b.dataset.defaut==='1');\n    b.className = 'cbtn'+(ordre[b.dataset.cle]===b.dataset.val?' actif':'');\n  });\n}\n/* Traduit les boutons en ordre pour coin.js. Rien n'est envoye si le coach\n   n'a rien demande : un round sans consigne doit rester un round sans\n   consigne, pas un gameplan \"neutre\" ecrit par l'ecran. */\nfunction ordreCoin(){\n  const o={};\n  if(ordre.plan==='frappe'){o.striking=6;o.wrestling=2;o.clinch=2}\n  else if(ordre.plan==='lutte'){o.striking=2;o.wrestling=6;o.clinch=2}\n  else if(ordre.plan==='clinch'){o.striking=2;o.wrestling=2;o.clinch=6}\n  if(ordre.allure==='eco')o.allure=0.8;\n  else if(ordre.allure==='fort')o.allure=1.25;\n  if(ordre.cible)o.cible=ordre.cible;\n  if(ordre.sol)o.sol=ordre.sol;\n  return Object.keys(o).length?o:null;\n}\nfunction reprendre(){\n  $('coach').classList.remove('la');\n  /* /!\\ IL NE PARLE PLUS DU ROUND D'AVANT. Sans ca, la cloche suivante\n     rouvrait le coin sur le ressenti perime tant que le jeu n'en avait\n     pas renvoye un — et l'ecran aurait menti d'un round entier. */\n  RESSENTI=null;\n  const o=ordreCoin();\n  envoyer({mma:\"reprendre\",ordre:o});\n}\nfunction envoyer(m){\n  if(window.parent&&window.parent!==window)window.parent.postMessage(m,\"*\");\n}\n/* Le jeu renvoie la chronologie du log COMPLET. On remplace S et on se\n   recale par le TEMPS, pas par l'index : les etapes deja jouees ont pu\n   etre reecrites. */\nwindow.addEventListener(\"message\",e=>{\n  const m=e&&e.data; if(!m||m.mma!==\"suite\")return;\n  /* /!\\ L'ECOULE SE CAPTURE AVANT DE REMPLACER S (Mael, 16/08 : chrono\n     fige a 5:00). tM0=ecoule() etait calcule APRES S=m.S — la fraction\n     se mesurait sur la nouvelle liste, plus longue a chaque tranche,\n     donc ecrasee vers zero : le chrono restait colle en haut de round. */\n  const eAvant=ecoule();\n  S=m.S;\n  /* CHANTIER G : l'etat de tranche et l'echo du cri. */\n  const etaitTranche=attenteTranche;\n  attenteTranche=false;\n  if(m.finRound!==undefined)finRound=m.finRound;\n  /* CE QU'IL DIT AU COIN. Le jeu l'envoie avec la tranche qui clot le\n     round — l'ecran ne le CALCULE pas, il ne fait que le rendre : le\n     ressenti sort du moteur (js/ressenti.js), jamais d'ici. */\n  if(m.ressenti!==undefined)RESSENTI=m.ressenti;\n  if($('crier').classList.contains('la'))majCris();\n  if(m.criMot){\n    /* /!\\ LE CRI SE VOIT (Mael, 21/08 : \"crier on voit pas bien le\n       resultat\") : l'echo passait par la ligne de commentaire, noye dans\n       le flux. Desormais un bandeau dedie au-dessus de la cage — dore si\n       le cri porte, gris s'il se perd ou arrive trop tard — visible ~2,6 s. */\n    const e=$('criEcho');\n    e.textContent=m.criMot;\n    e.classList.toggle('perdu',/trop tard|couvre|n'entend|bruit/i.test(m.criMot));\n    e.classList.remove('on');void e.offsetWidth;e.classList.add('on');\n    clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('on'),2600);\n  }\n  /* La fenetre de temps moteur de la tranche recue : l'horloge\n     progressera de tM0 a tM1 pendant sa lecture. En fin de round, la\n     borne haute est le temps de la derniere etape (recalee par le\n     verdict) — l'heure d'un KO reste la vraie. */\n  if(etaitTranche||m.finRound!==undefined){\n    tM0=Math.max(0,Math.min(SEC_RD,eAvant));\n    if(m.tMoteur!=null)tM1=m.tMoteur;\n    else if(m.finRound&&m.S&&m.S.length)\n      tM1=Math.max(0,Math.min(SEC_RD,m.S[m.S.length-1].t-(RD-1)*SEC_RD));\n    else tM1=Math.min(SEC_RD,tM0+30);\n  }\n  /* /!\\ FIN S'ASSIGNE AVANT TOUT CHEMIN (crash vu par Mael, 15/08 : KO\n     pendant SIMULER -> le bloc d'avalage tournait AVANT l'assignation ->\n     la fin de combat s'appliquait sans FIN -> pas de carte -> CLOCHE\n     FANTOME -> le joueur donne un plan -> consigne() jette \"le combat\n     est termine\". La fin du combat prime sur tout le reste. */\n  if(m.FIN)FIN=m.FIN;\n  if(m.feuille&&typeof FEUILLE_MAJ===\"function\")FEUILLE_MAJ(m.feuille);\n  if(m.cartes){CARTES=m.cartes;majCartes();}\n  if(sauteRound){\n    /* Meme regle : index garde, pli, puis on avale jusqu'a la borne —\n       la fin provisoire d'une TRANCHE ne se joue jamais. */\n    if(etaitTranche){\n      i=Math.min(i,S.length-1);\n      iBase=i;\n      replierEtat();\n      retemporiser();\n    }\n    const borne=finRound?S.length:S.length-1;\n    while(i+1<borne){i++;etape=S[i];applique(etape);t=etape.t;}\n    suiv=S[i+1]; horloge(); majDirect();\n    if(!finRound){demanderTranche();return}\n    sauteRound=false;\n    if(!fini)cloche();\n    return;\n  }\n  /* /!\\ UNE TRANCHE N'EST PAS UNE REPRISE DE ROUND (defaut vu par Mael,\n     15/08 : compteurs a 214/563 pour 12 frappes reelles — puis, premiere\n     correction, des PERTES : le reliquat redistribue passait sous le\n     recalage par temps). La regle finale : INDEX GARDE, chronologie de la\n     nouvelle liste adoptee, et PLI — voir replierEtat(). */\n  if(etaitTranche){\n    i=Math.min(i,S.length-1);\n    iBase=i;\n    replierEtat();\n    retemporiser();\n    etape=S[i]; suiv=S[i+1];\n    return;\n  }\n  i=0; while(i+1<S.length&&S[i+1].t<=t)i++;\n  etape=S[i]; suiv=S[i+1];\n\n  /* /!\\ BUG VU EN VRAI : l'ecran restait sur \"ROUND 1 0:00\" apres la\n     reprise. RD n'est mis a jour que DANS applique(), or les etapes\n     franchies par le recalage ne sont PAS rejouees — sinon on doublerait\n     les statistiques. L'etape de transition du round suivant (rd:2, posee\n     a t≈300) se retrouvait donc DERRIERE l'index et n'etait jamais\n     appliquee. On relit le round directement dans les etapes deja passees. */\n  let rdVu=1;\n  for(let k=0;k<=i;k++) if(S[k].rd!==undefined) rdVu=S[k].rd;\n  if(rdVu!==RD){\n    RD=rdVu;\n    const g=$('gong');g.textContent=`ROUND ${RD}`;\n    g.classList.remove('on');void g.offsetWidth;g.classList.add('on');\n  }\n  /* Le round commence a sa seconde 0, pas la ou la cloche a sonne : sans\n     ca on entamait le round suivant avec 4 s deja consommees (le temps de\n     respiration que le traducteur ajoute en fin de log). */\n  t=Math.max(t,(RD-1)*SEC_RD);\n  if(t>(RD-1)*SEC_RD+1) t=(RD-1)*SEC_RD;\n  horloge();\n\n  attenteCoin=false; enPause=false;\n  tM0=0; if(m.tMoteur!=null)tM1=m.tMoteur; iBase=i;\n  /* /!\\ LA REPRISE DE ROUND REPLIE AUSSI (Mael, 16/08 : \"ils sont en\n     dehors de la cage\", DEMI-GARDE affiche en pleine DISTANCE). Les\n     etapes franchies par le recalage ne sont pas rejouees — l'etat\n     VISUEL (position au sol, points sur la grille, phase) restait donc\n     celui de la fin du round precedent. Le pli remet tout : compteurs,\n     grille, phase, round — depuis la liste fraiche, en muet.\n     /!\\ LE PLI D'ABORD, LA RETEMPORISATION ENSUITE : retemporiser()\n     depend du round courant — le lancer avant le pli l'ancrait sur le\n     round precedent (invariant du banc rompu, 16/08). */\n  replierEtat();\n  /* /!\\ SEULEMENT SI LE TEMPS MOTEUR EST FOURNI : sans lui (un \"suite\"\n     a l'ancienne, round entier), retemporiser sur une fenetre par\n     defaut de 30 s COMPRESSAIT tout le round — et avalait les\n     suivants (invariant du banc, 16/08). Pas d'info moteur, pas de\n     reecriture : la chronologie du traducteur reste. */\n  if(m.tMoteur!=null)retemporiser();\n  $('btnPause').textContent='⏸ PAUSE';\n});\n\nfunction rejouer(){\n  if(window.parent && window.parent!==window)\n    window.parent.postMessage({mma:\"rejouer\"},\"*\");\n  else location.reload();\n}\nlet   FIN    = DATA.FIN;\n/* ============ MODE DIRECT ============\n   DATA.direct : le combat n'est PAS roule d'avance. L'ecran joue le round\n   qu'on lui a donne, s'arrete a la cloche, ouvre le coin, et demande la\n   suite au jeu (postMessage). Le jeu joue le round suivant avec coin.js,\n   retraduit le log COMPLET hors flux, et renvoie une nouvelle chronologie.\n   /!\\ On remplace S en entier a chaque round, on ne concatene PAS des\n   tranches : le traducteur reecrit la derniere etape du round precedent\n   (4 s de respiration qui deviennent une transition). Voir le carnet. */\nconst DIRECT = !!DATA.direct;\nlet attenteCoin=false, ordre={};\n/* ==== CHANTIER G : LES CRIS ====\n   finRound : la derniere tranche recue clot-elle le round ? Si non, a\n   court d'etapes on demande la SUIVANTE au jeu, automatiquement — le\n   combat coule. criEnAttente part avec cette demande et s'applique a la\n   tranche qui n'est pas encore calculee : l'ecran ne ment jamais.\n   crisRestants : trois par round (regle de Mael), remis a la cloche. */\nlet finRound = DATA.finRound!==undefined?DATA.finRound:true;\n/* /!\\ LE PANNEAU SUIT LA PHASE VISIBLE, PAS CELLE DU MOTEUR (defaut vu\n   par Mael, 15/08 : cris du sol proposes debout contre la grille). Le\n   moteur est UNE TRANCHE EN AVANCE sur la lecture — ses cris decrivaient\n   un futur que le joueur ne voyait pas encore. L'ecran filtre donc le\n   vocabulaire complet (DATA.vocabCris) sur ce qui est A L'IMAGE ; le jeu\n   verifie a l'application et repond \"trop tard\" si ca a change. */\nconst VOCAB_CRIS = DATA.vocabCris||[];\n/* /!\\ L'HORLOGE DIT LE TEMPS DU MOTEUR (Mael, 15/08 : \"le combat\n   continuait meme a 0 sec timer\"). La chronologie du traducteur est\n   FICTIVE et se re-etale a chaque retraduction — decalage cumule =\n   derive = un chrono a 0:00 pendant que le combat continue. Le moteur,\n   lui, donne son temps REEL a chaque arret de tranche : l'ecran\n   interpole l'affichage entre deux arrets (tM0 -> tM1) selon la\n   progression des etapes. Le chrono raconte le combat calcule, plus la\n   fiction du traducteur. */\nlet tM0=0, tM1=(DATA.tMoteur!=null?DATA.tMoteur:30), iBase=0;\nlet solVisible=\"\", ctrlVisible=null, phVisible=\"DISTANCE\";\nfunction phaseVisible(){\n  if(solVisible)return ctrlVisible==='A'?'sol_dessus':'sol_dessous';\n  if(phVisible==='CLINCH')return 'clinch';\n  return 'debout';\n}\nlet criEnAttente=null, crisRestants=3, attenteTranche=false;\nfunction ouvrirCris(){\n  if(!DIRECT||fini)return;\n  const z=$('crier');\n  if(z.classList.contains('la')){z.classList.remove('la');return;}\n  majCris(); z.classList.add('la');\n}\nfunction majCris(){\n  $('crReste').textContent=crisRestants>0\n    ?`${crisRestants} cri${crisRestants>1?'s':''} restant${crisRestants>1?'s':''} ce round`\n    :\"plus de voix ce round\";\n  const ph=phaseVisible();\n  const dispo=VOCAB_CRIS.filter(c=>c.phase===ph||c.phase==='toute');\n  $('crListe').innerHTML=dispo.map(c=>\n    `<button class=\"cri-b ${criEnAttente===c.id?'choisi':''}\"\n      onclick=\"choisirCri('${c.id}')\">${c.mot}</button>`).join('')\n    ||'<span style=\"font-size:.7rem;color:var(--craie-2)\">La reprise arrive…</span>';\n}\nfunction choisirCri(id){\n  if(crisRestants<=0)return;\n  criEnAttente=(criEnAttente===id)?null:id;\n  $('btnCrier').classList.toggle('arme',!!criEnAttente);\n  majCris();\n  if(criEnAttente)$('crier').classList.remove('la');\n}\nfunction demanderTranche(){\n  if(attenteTranche)return;\n  attenteTranche=true;\n  const cri=criEnAttente; criEnAttente=null;\n  if(cri){crisRestants--; $('btnCrier').classList.remove('arme');}\n  envoyer({mma:\"tranche\",cri:cri||null});\n}\nconst NOMS   = DATA.noms;\nconst FICHES = DATA.fiches || [\"\",\"\"];\nconst PROFIL = DATA.profils || [];\nconst BOURSE = DATA.bourse || \"\";\nconst SEC_RD = DATA.sec_round || 300;\n\n/* ============ ETAT ============ */\nconst $=id=>document.getElementById(id);\nconst pA=$('pA'),pB=$('pB');\nconst DMG=['#232b36','#7a4a33','#b6412f','#e33b28'];\nconst niveaux={At:0,Ac:0,Aj:0,Bt:0,Bc:0,Bj:0};\nconst V={sigA:0,frA:0,sigB:0,frB:0,tdA:[0,0],tdB:[0,0],ctA:0,ctB:0,subA:0,subB:0};\nlet ctrl=null, knockA=0, knockB=0;\nlet i=0,t=0,mult=1,ralenti=1,enPause=false,pauseAvant=false,essA=100,essB=100,fini=false;\nlet RD=1;\n\nconst mmss=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;\nconst nom=c=>NOMS[c==='A'?0:1];\n\n/* Horloge multi-rounds : `t` est ABSOLU dans la sortie du traducteur.\n   Le round courant vient du champ `rd` (present sur l'etape de reprise) ;\n   a defaut on retombe sur le decoupage par SEC_RD. */\n/* /!\\ UNE SEULE CHRONOLOGIE (Mael, 16/08 : \"le chrono baisse super\n   lentement\") : le rythme de lecture suivait la chronologie FICTIVE du\n   traducteur (etalee) pendant que le chrono suivait le temps moteur\n   (30 s par tranche) — a x8 on regardait du x1,5. La regle du carnet\n   s'applique jusqu'au bout : LE TEMPS MOTEUR EST LE MAITRE, du chrono\n   ET du rythme. retemporiser() reecrit les temps des etapes a venir,\n   uniformement sur la fenetre moteur de la tranche — t redevient le\n   temps du combat, x8 veut dire x8. */\nfunction retemporiser(){\n  const tAbs1=(RD-1)*SEC_RD+Math.max(0,Math.min(SEC_RD,tM1!=null?tM1:30));\n  const borne=Math.min(S.length-1,finRound?S.length-1:S.length-2);\n  const n=Math.max(1,borne-i);\n  const t0=Math.max(t,(RD-1)*SEC_RD);\n  for(let k=i+1;k<=borne;k++)\n    S[k].t=t0+(k-i)/n*Math.max(0.5,tAbs1-t0);\n  if(!finRound&&S.length-1>borne)S[S.length-1].t=tAbs1+4;\n}\nfunction ecoule(){return Math.max(0,Math.min(SEC_RD,t-(RD-1)*SEC_RD))}\nfunction horloge(){\n  const r=SEC_RD-ecoule();\n  $('clk').textContent=`${Math.floor(r/60)}:${String(Math.floor(r%60)).padStart(2,'0')}`;\n  $('rnd').textContent=`ROUND ${RD}`;\n}\n/* Le temps d'un evenement, en langage de fiche : \"R2 4:17\".\n   /!\\ La derniere etape du traducteur porte t_abs+4 (respiration avant la\n   carte) : sans borne, une fin de round s'affiche \"5:01\" dans un round de\n   5:00 — l'ecran raconterait une seconde qui n'existe pas. */\nconst marque=tt=>{const r=Math.min(RD,Math.floor(tt/SEC_RD)+1);\n  return `R${r} ${mmss(Math.min(SEC_RD,tt-(r-1)*SEC_RD))}`};\n\n/* ============ LES CARTES DES JUGES ============\n   /!\\ ON N'AFFICHE QUE LES ROUNDS TERMINES : montrer le round en cours\n   reviendrait a dire au joueur qui gagne avant la cloche. */\nlet CARTES = DATA.cartes || [];\nfunction majCartes(){\n  const z=$('cartes');\n  if(!CARTES.length){z.innerHTML='';return;}\n  let ta=0,tb=0;\n  const cases=CARTES.map(c=>{ta+=c.a;tb+=c.b;\n    return `<span class=\"c\"><small>R${c.rd}</small>`\n      +`<span class=\"${c.a>c.b?'g':''}\">${c.a}</span>-`\n      +`<span class=\"${c.b>c.a?'d':''}\">${c.b}</span></span>`;});\n  if(CARTES.length>1)cases.push(`<span class=\"c tot\">`\n    +`<span class=\"${ta>tb?'g':''}\">${ta}</span>-<span class=\"${tb>ta?'d':''}\">${tb}</span></span>`);\n  z.innerHTML=cases.join('');\n}\n\nfunction majDirect(){\n  $('dSig').innerHTML=`<span class=\"g\">${V.sigA}</span><span class=\"sep\">–</span><span class=\"d\">${V.sigB}</span>`;\n  $('dFr').innerHTML =`<span class=\"g\">${V.frA}</span><span class=\"sep\">–</span><span class=\"d\">${V.frB}</span>`;\n  $('dTd').innerHTML =`<span class=\"g\">${V.tdA[0]}/${V.tdA[1]}</span><span class=\"sep\">–</span><span class=\"d\">${V.tdB[0]}/${V.tdB[1]}</span>`;\n  $('dCt').innerHTML =`<span class=\"g\">${mmss(V.ctA)}</span><span class=\"sep\">–</span><span class=\"d\">${mmss(V.ctB)}</span>`;\n  $('dSub').innerHTML=`<span class=\"g\">${V.subA}</span><span class=\"sep\">–</span><span class=\"d\">${V.subB}</span>`;\n}\n\n/* ============ CARTE DE FIN ============ */\nconst LIB={SOUMISSION:\"Soumission\",KO:\"KO\",TKO:\"TKO\",\n           \"DÉCISION\":\"Décision\",\"ARRÊT\":\"Arrêt\",\"NUL\":\"Match nul\"};\n/* VERDICT (optionnel) vient de verdict.js : c'est la MEME phrase que celle\n   du palmares du jeu. Quand il est fourni, l'ecran anime et la carte de\n   resultat parlent d'une seule voix. Absent (ecran autonome produit par\n   rendu_combat.py), on retombe sur l'ancienne redaction. */\nconst VERDICT = DATA.verdict || null;\nfunction carteFin(){\n  fini=true;\n  const tFin=S[S.length-1].t, m=FIN.methode, v=FIN.vainqueur;\n  let detail;\n  if(VERDICT){\n    const quand = m===\"DÉCISION\" ? `${RD} rounds` : marque(tFin);\n    const tete  = VERDICT.libelle.charAt(0).toUpperCase()+VERDICT.libelle.slice(1);\n    detail = `${tete} · ${quand}`;\n  }\n  else if(m===\"SOUMISSION\") detail=`Soumission — ${FIN.detail||''} · ${marque(tFin)}`;\n  else if(m===\"KO\")     detail=`KO · ${marque(tFin)}`;\n  else if(m===\"TKO\")    detail=`TKO — l'arbitre arrête · ${marque(tFin)}`;\n  else if(m===\"DÉCISION\") detail=v?`Décision · ${RD} rounds`:`Match nul · ${RD} rounds`;\n  else                  detail=`${LIB[m]||m} · ${marque(tFin)}`;\n\n  $('finTitre').textContent = v?\"VICTOIRE\":\"MATCH NUL\";\n  $('finNom').textContent   = v?nom(v):`${NOMS[0]} — ${NOMS[1]}`;\n  $('finMethode').textContent = detail;\n  $('finBourse').textContent  = BOURSE;\n  $('verdict').textContent    = (v?`${nom(v).toUpperCase()} · `:'')+detail.toUpperCase();\n  $('fin').classList.add('la');\n}\n\nfunction applique(e,muet){\n  /* L'etape de fin porte les frappes accumulees depuis la derniere etape\n     emise (traducteur). Les verser AVANT la carte, sinon la fin du combat\n     manque au tableau : 4/7 et 10/12 affiches pour 4/8 et 11/17 reels. */\n  if(e.fin){\n    if(e.st){V.sigA+=e.st[0];V.frA+=e.st[1];V.sigB+=e.st[2];V.frB+=e.st[3];majDirect()}\n    /* /!\\ EN MODE DIRECT, le traducteur marque la fin du log qu'on lui a\n       donne — donc la fin du ROUND joue, pas celle du combat. Tant que le\n       jeu n'a pas envoye FIN, ce n'est qu'une cloche : on verse les stats\n       et on laisse la boucle appeler cloche(). */\n    if(DIRECT&&!FIN)return;\n    carteFin();return\n  }\n  if(e.rd!==undefined&&e.rd!==RD){\n    RD=e.rd;\n    if(!muet){const g=$('gong');g.textContent=`ROUND ${RD}`;\n    g.classList.remove('on');void g.offsetWidth;g.classList.add('on');}\n  }\n  if(e.com){const c=$('com');c.textContent=e.com;\n    if(!muet){c.classList.remove('pop');void c.offsetWidth;c.classList.add('pop')}}\n  const ph=$('phase');ph.textContent=e.ph;ph.classList.toggle('chaud',!!e.chaud);\n  if(e.mom!==undefined)$('mom').style.width=e.mom+'%';\n  if(e.flash&&!muet){const f=$('flash');f.classList.remove('on');void f.offsetWidth;f.classList.add('on');\n    if(navigator.vibrate)navigator.vibrate(40)}\n  if(e.dmg)for(const[z,n]of Object.entries(e.dmg)){\n    niveaux[z]=Math.min(3,niveaux[z]+n);$(z).style.fill=DMG[niveaux[z]];\n    const j=$(z+'2');if(j)j.style.fill=DMG[niveaux[z]];\n  }\n  /* knockdown : le traducteur le dit explicitement (champ kd = celui qui\n     TOMBE). On ne le devine plus a partir des degats. */\n  if(e.kd){if(e.kd==='A')knockA++;else knockB++}\n  if(e.st){V.sigA+=e.st[0];V.frA+=e.st[1];V.sigB+=e.st[2];V.frB+=e.st[3]}\n  if(e.tdA){V.tdA[0]+=e.tdA[0];V.tdA[1]+=e.tdA[1]}\n  if(e.tdB){V.tdB[0]+=e.tdB[0];V.tdB[1]+=e.tdB[1]}\n  if(e.subA)V.subA+=e.subA; if(e.subB)V.subB+=e.subB;\n  if(e.ctrl!==undefined)ctrl=e.ctrl||null;\n  const sol=$('posSol');\n  if(e.sol!==undefined){sol.textContent=e.sol||'';sol.setAttribute('opacity',e.sol?1:0);\n    solVisible=e.sol||''}\n  if(e.ph)phVisible=e.ph;\n  if(e.ctrl!==undefined)ctrlVisible=e.ctrl||null;\n  if(!muet&&$('crier').classList.contains('la'))majCris();\n  ralenti=e.slow?0.35:1;\n  majDirect();\n}\n/* /!\\ LE PLI (defaut vu par Mael, 15/08 : \"Frappes sign. 214/563\" pour 12\n   frappes reelles). Le traducteur RE-TEMPORISE tout le round a chaque\n   retraduction : aucun recalage par temps ne peut etre juste en cours de\n   round, et une accumulation incrementale derive — en double (rejeu) ou\n   en perte (reliquat redistribue). Verifie sur banc : le CONTENU hors\n   temps est un prefixe stable — donc on garde L'INDEX, on adopte la\n   nouvelle chronologie, et on RECONSTRUIT tous les compteurs en repliant\n   la liste fraiche de 0 a i. L'ecran ne compte plus : il reflete. */\nfunction replierEtat(){\n  V.sigA=0;V.frA=0;V.sigB=0;V.frB=0;V.tdA=[0,0];V.tdB=[0,0];\n  /* /!\\ LE CONTROLE NE RECULE JAMAIS (Mael, 21/08 : \"5:30 -> 4:30\n     pendant le combat\") : le recalcul par etapes repartait de zero sur\n     une chronologie RETEMPORISEE (compressee) — il rendait moins que le\n     cumul du tick temps-reel. Deux horloges pour un meme compteur : on\n     garde LE MAX. L'ecran est indicatif, le verdict lit le moteur. */\n  const ctA0=V.ctA||0, ctB0=V.ctB||0;\n  V.subA=0;V.subB=0;V.ctA=0;V.ctB=0;knockA=0;knockB=0;ctrl=null;\n  for(const z in niveaux){niveaux[z]=0;$(z).style.fill=DMG[0];\n    const j=$(z+'2');if(j)j.style.fill=DMG[0];}\n  RD=1;\n  for(let k=0;k<=i&&k<S.length;k++){\n    /* le controle s'integre entre les etapes, comme la boucle le fait */\n    if(k>0&&ctrl){const dt=Math.max(0,S[k].t-S[k-1].t);\n      if(ctrl==='A')V.ctA+=dt;else V.ctB+=dt;}\n    applique(S[k],true);\n  }\n  V.ctA=Math.max(V.ctA,ctA0);V.ctB=Math.max(V.ctB,ctB0);\n  majDirect();horloge();\n}\nfunction pos(el,x,y){el.setAttribute('transform',`translate(${x},${y})`)}\n\n/* ============ DEMARRAGE ============ */\nconst pts=[...Array(8)].map((_,k)=>{const a=Math.PI/8+k*Math.PI/4;\n  return [180+158*Math.cos(a),180+158*Math.sin(a)]});\n$('oct').setAttribute('points',pts.map(p=>p.join(',')).join(' '));\n$('oct2').setAttribute('points',pts.map(([x,y])=>\n  [180+(x-180)*.9,180+(y-180)*.9].join(',')).join(' '));\n\nif(!DIRECT)$('btnCrier').style.display='none';\n$('nomA').textContent=$('sNomA').textContent=NOMS[0];\n$('nomB').textContent=$('sNomB').textContent=NOMS[1];\n$('ficheA').textContent=FICHES[0];$('ficheB').textContent=FICHES[1];\n\nlet etape=S[0],suiv=S[1];\n/* /!\\ LA PREMIERE TRANCHE SE RETEMPORISE AUSSI (Mael, 21/08 : \"round 1\n   bug, tout se joue dans les 10 dernieres secondes\" + \"mon cri met plus\n   d'1 min a arriver\"). La tranche initiale etait lue avec la chronologie\n   DU TRADUCTEUR — etalee sur les 300 s du round : la lecture trainait,\n   puis chaque retemporisation compressait le reste en fin de round, et\n   la reponse au cri attendait la fin de cette lecture interminable. Le\n   temps moteur est le maitre DES LE PREMIER INSTANT. */\nif(DIRECT&&!FIN&&DATA.tMoteur!=null)retemporiser();\napplique(etape);pos(pA,...etape.a);pos(pB,...etape.b);majDirect();majCartes();horloge();\n\nconst boucle=setInterval(()=>{\n  if(enPause||fini)return;\n  const dt=0.06*mult*ralenti;\n  t+=dt;\n  if(ctrl==='A')V.ctA+=dt; if(ctrl==='B'){V.ctB+=dt;majDirect()}\n  /* PLACEHOLDER : l'essence n'est PAS encore fournie par le traducteur.\n     Décroissance identique des deux côtés — l'écran ne prétend donc rien\n     sur qui gaze. A brancher sur le cardio du moteur. */\n  essA=essB=Math.max(14,100-ecoule()/SEC_RD*22-(RD-1)*16);\n  $('essA').style.width=essA+'%';$('essB').style.width=essB+'%';\n  horloge();\n  while(suiv&&t>=suiv.t){\n    /* La fin provisoire d'une TRANCHE ne se joue pas (voir sauteRound) :\n       on s'arrete devant et on demande la suite. */\n    if(DIRECT&&!fini&&!finRound&&i+2===S.length)break;\n    etape=suiv;applique(etape);i++;suiv=S[i+1]}\n  if(DIRECT&&!fini&&!attenteCoin&&!finRound&&suiv&&i+2===S.length){\n    demanderTranche();/* la lecture continue pendant que le jeu calcule */}\n  /* Plus d'etape a jouer et le combat n'est pas fini : la tranche\n     suivante si le round court encore, la cloche s'il est termine. */\n  if(DIRECT&&!suiv&&!fini&&!attenteCoin){\n    if(!finRound){demanderTranche();return}\n    cloche();return}\n  if(suiv&&etape.a){\n    const k=Math.min(1,(t-etape.t)/Math.max(.001,suiv.t-etape.t));\n    const l=(p,q)=>p+(q-p)*k;\n    const der=Math.sin(t*2.6)*3;\n    pos(pA,l(etape.a[0],(suiv.a||etape.a)[0])+der,l(etape.a[1],(suiv.a||etape.a)[1]));\n    pos(pB,l(etape.b[0],(suiv.b||etape.b)[0])-der,l(etape.b[1],(suiv.b||etape.b)[1]));\n  }\n},60);\n\n/* ============ FEUILLE ============ */\n/* ============ FRAPPES SIGNIFICATIVES (format ufcstats) ============\n   DATA.feuille vient de feuille.js : repartition par CIBLE et par POSITION,\n   round par round.\n   /!\\ CE BLOC NE DOIT JAMAIS DEVOILER L'AVENIR. La feuille contient le\n   combat ENTIER des le depart ; l'afficher tel quel dirait au joueur, au\n   round 1, combien de coups il prendra au round 3. On ne cumule donc que\n   les rounds DEJA JOUES — le round en cours reste dans les compteurs\n   vivants de \"LE COMBAT\", au-dessus. */\n/* /!\\ LA FEUILLE SUIT LE DIRECT (22/08, dossier \"feuille croisee\" de\n   Mael : recap \"tout en A\", detail fige). FEUILLE_MAJ etait appelee au\n   protocole (415) mais N'EXISTAIT NULLE PART — la feuille recalculee\n   envoyee a chaque tranche etait JETEE : en direct, le detail des zones\n   restait fige sur la feuille du BOOT (le R1 partiel). Desormais la\n   feuille se met a jour, et c'est ELLE — la verite recalculee du log —\n   que lit le recap de fin. */\nlet FEUILLE = DATA.feuille || null;\nfunction FEUILLE_MAJ(f){ FEUILLE=f; }\nlet parRound = false;   /* le depliant \"PER ROUND\" d'ufcstats */\n\n/** Rounds entierement joues : RD-1 en cours de combat, tous a la fin. */\nfunction roundsAcquis(){\n  if(!FEUILLE) return 0;\n  return Math.max(0, Math.min(FEUILLE.rounds.length, fini ? FEUILLE.rounds.length : RD-1));\n}\nfunction cumul(cote, jusqua){\n  const vide={sig:[0,0],tete:[0,0],corps:[0,0],jambe:[0,0],\n              distance:[0,0],clinch:[0,0],sol:[0,0]};\n  for(let r=0;r<jusqua;r++){const s=FEUILLE.rounds[r][cote];\n    for(const k in vide){vide[k][0]+=s[k][0];vide[k][1]+=s[k][1];}}\n  return vide;\n}\nconst surTotal=p=>`${p[0]} of ${p[1]}`;\n\nfunction ligneFrappes(lib,pa,pb){\n  const m=Math.max(pa[0],pb[0],1);\n  return `<div class=\"ligne\"><b class=\"${pa[0]>pb[0]?'gagne':''}\">${surTotal(pa)}</b>\n    <div class=\"demi g\"><i style=\"width:${pa[0]/m*100}%\"></i></div>\n    <span class=\"lib\">${lib}</span>\n    <div class=\"demi d\"><i style=\"width:${pb[0]/m*100}%\"></i></div>\n    <b class=\"${pb[0]>pa[0]?'gagne':''}\">${surTotal(pb)}</b></div>`;\n}\n\nfunction basculerRounds(){parRound=!parRound;rendreFrappes();}\n\nfunction rendreFrappes(){\n  const cible=$('lignes-frappes'), titre=$('tete-frappes');\n  if(!FEUILLE){\n    titre.textContent=\"FRAPPES SIGNIFICATIVES\";\n    cible.innerHTML='<div style=\"text-align:center;font-size:.7rem;color:var(--craie-2)\">'\n      +'Répartition non fournie par le moteur.</div>';\n    return;\n  }\n  const n=roundsAcquis();\n  titre.innerHTML=`FRAPPES SIGNIFICATIVES`\n    + (n>1?` <span onclick=\"basculerRounds()\" style=\"cursor:pointer;color:var(--tungstene);`\n        +`font-size:.62rem;letter-spacing:.04em\">${parRound?'▼ CUMUL':'▶ PAR ROUND'}</span>`:'');\n\n  if(n===0){\n    cible.innerHTML='<div style=\"text-align:center;font-size:.7rem;color:var(--craie-2)\">'\n      +`Round ${RD} en cours — la répartition s'affiche round terminé.</div>`;\n    return;\n  }\n\n  let html='';\n  const bloc=(a,b)=>ligneFrappes('Tête',a.tete,b.tete)\n    +ligneFrappes('Corps',a.corps,b.corps)\n    +ligneFrappes('Jambes',a.jambe,b.jambe)\n    +`<div class=\"ligne\" style=\"opacity:.55\"><b></b><div class=\"demi g\"></div>`\n    +`<span class=\"lib\">— position —</span><div class=\"demi d\"></div><b></b></div>`\n    +ligneFrappes('Distance',a.distance,b.distance)\n    +ligneFrappes('Clinch',a.clinch,b.clinch)\n    +ligneFrappes('Au sol',a.sol,b.sol);\n\n  if(parRound){\n    for(let r=0;r<n;r++){\n      html+=`<div class=\"lib\" style=\"text-align:center;margin:8px 0 3px;`\n        +`font-size:.62rem;letter-spacing:.08em;color:var(--tungstene)\">ROUND ${r+1}</div>`;\n      html+=bloc(FEUILLE.rounds[r][0],FEUILLE.rounds[r][1]);\n    }\n  }else{\n    html=bloc(cumul(0,n),cumul(1,n));\n    if(!fini) html+=`<div class=\"lib\" style=\"text-align:center;margin-top:6px;font-size:.6rem;`\n      +`color:var(--craie-2)\">cumul après ${n} round${n>1?'s':''} · le round ${RD} est en cours</div>`;\n  }\n  cible.innerHTML=html;\n}\n\nfunction rendreFeuille(){\n  const pc=a=>a[1]?Math.round(a[0]/a[1]*100):0;\n  /* /!\\ LE RECAP DE FIN DIT CE QUE LE MOTEUR A CALCULE (22/08) : la\n     feuille (recalculee depuis le log complet) prime sur les compteurs\n     vecus de la lecture — le live ne sert qu'au bandeau du direct. */\n  const T=FEUILLE&&FEUILLE.total?FEUILLE.total:null;\n  const sA=T?T[0].sig:[V.sigA,V.frA], sB=T?T[1].sig:[V.sigB,V.frB];\n  const tA=T?T[0].td:V.tdA,           tB=T?T[1].td:V.tdB;\n  const uA=T?T[0].sub:V.subA,         uB=T?T[1].sub:V.subB;\n  const cA=T?T[0].controle:V.ctA,     cB=T?T[1].controle:V.ctB;\n  /* kd de la feuille = INFLIGES par le cote (m[1] tombe, 1-c credite le\n     frappeur) : la gauche lit T[0].kd — verifie sur feuille.js:187. */\n  const kA=T?T[0].kd:knockB,          kB=T?T[1].kd:knockA;\n  const C=[\n    [\"Frappes sign.\",`${sA[0]} / ${sA[1]}`,sA[0],sB[0],`${sB[0]} / ${sB[1]}`],\n    [\"Précision\",`${pc(sA)} %`,pc(sA),pc(sB),`${pc(sB)} %`],\n    [\"Takedowns\",`${tA[0]} / ${tA[1]}`,tA[0]*10,tB[0]*10,`${tB[0]} / ${tB[1]}`],\n    [\"Contrôle\",mmss(cA),cA,cB,mmss(cB)],\n    [\"Tent. soumission\",String(uA),uA*20,uB*20,String(uB)],\n    [\"Knockdowns\",String(kA),kA*40,kB*40,String(kB)],\n  ];\n  const rend=(cible,lignes,max)=>{$(cible).innerHTML=lignes.map(l=>{\n    const [lib,tg,vg,vd,td]=l.length===5?l:[l[0],l[1],l[1],l[2],l[2]];\n    const m=max||Math.max(vg,vd,1);\n    return `<div class=\"ligne\"><b class=\"${vg>vd?'gagne':''}\">${tg}</b>\n      <div class=\"demi g\"><i style=\"width:${vg/m*100}%\"></i></div>\n      <span class=\"lib\">${lib}</span>\n      <div class=\"demi d\"><i style=\"width:${vd/m*100}%\"></i></div>\n      <b class=\"${vd>vg?'gagne':''}\">${td}</b></div>`}).join('')};\n  rend('lignes-combat',C);\n  rendreFrappes();\n  if(PROFIL.length){rend('lignes-profil',PROFIL,100)}\n  else{$('lignes-profil').innerHTML=\n    '<div style=\"text-align:center;font-size:.7rem;color:var(--craie-2)\">Profils non fournis par le moteur.</div>'}\n  if(!fini)$('verdict').textContent=`ROUND ${RD} · ${$('clk').textContent} · EN COURS`;\n}\nfunction voirStats(){pauseAvant=enPause;enPause=true;rendreFeuille();$('stats').classList.add('la')}\nfunction fermerStats(){$('stats').classList.remove('la');if(!fini)enPause=pauseAvant;\n  $('btnPause').textContent=enPause?'▶ REPRENDRE':'⏸ PAUSE'}\nfunction pause(){enPause=!enPause;$('btnPause').textContent=enPause?'▶ REPRENDRE':'⏸ PAUSE'}\n/* 900 s de combat : x1 pour un temps fort, x8 pour traverser un round creux. */\n/* Sauter l'animation du round en cours : on applique toutes les etapes\n   restantes d'un coup et on laisse la boucle sonner la cloche. Le combat\n   n'est pas modifie — seule la vitesse de LECTURE change. */\nlet sauteRound=false;\nfunction simulerRound(){\n  if(fini||attenteCoin)return;\n  while(suiv){ t=suiv.t; etape=suiv; applique(etape); i++; suiv=S[i+1]; }\n  horloge(); majDirect();\n  /* CHANTIER G : le round n'est peut-etre calcule qu'a moitie — on avale\n     les tranches restantes une a une avant de sonner la cloche. */\n  if(DIRECT&&!finRound){sauteRound=true;demanderTranche();return}\n  if(DIRECT&&!fini)cloche();\n}\nfunction vitesse(){mult=mult===1?4:mult===4?8:1;$('btnVit').textContent=`×${mult}`}\n</script>\n</body>\n</html>\n",

    /** Gabarit + donnees -> page complete, prete pour un srcdoc d'iframe.
     *  Deux gardes : le point d'injection doit EXISTER (sinon replace ne fait
     *  rien en silence et la page produite a un `const DATA = ;`), et il ne
     *  doit plus en rester apres. */
    page: function (donnees) {
      if (this.gabarit.indexOf("/*__DATA__*/") < 0)
        throw new Error("MMA_ECRAN : gabarit sans point d'injection");
      // /!\ FONCTION, pas chaine : String.replace interprete $&, $` et $'
      // dans le remplacement, et un $ dans les donnees corromprait la page.
      const json = JSON.stringify(donnees);
      const html = this.gabarit.replace("/*__DATA__*/", () => json);
      if (html.includes("__DATA__")) throw new Error("MMA_ECRAN : injection ratee");
      return html;
    }
  };
})(typeof window !== "undefined" ? window : globalThis);
